local Control=require(script.Parent.Parent.Base.Control)
return function(ctx,pages,default,callback) local f=Instance.new("Frame",ctx.Parent);f.Name="Pagination";f.Size=UDim2.new(1,0,0,38);f.BackgroundTransparency=1;local c=Control.new(f,ctx,default or 1);local function button(text,x,fn)local b=Instance.new("TextButton",f);b.Position=UDim2.new(x,0,0,2);b.Size=UDim2.fromOffset(80,34);b.Text=text;b.BackgroundColor3=ctx.Theme:Get("SurfaceAlt");b.TextColor3=ctx.Theme:Get("Text");b.Font=Enum.Font.Gotham;b.TextSize=12;Instance.new("UICorner",b).CornerRadius=UDim.new(0,9);ctx.Input:BindPress(b,fn);end;local label=Instance.new("TextLabel",f);label.AnchorPoint=Vector2.new(.5,0);label.Position=UDim2.new(.5,0,0,0);label.Size=UDim2.fromOffset(100,38);label.BackgroundTransparency=1;label.TextColor3=ctx.Theme:Get("Text");label.Font=Enum.Font.Gotham;label.TextSize=13;local function render()label.Text=tostring(c.Value).." / "..tostring(pages or 1)end;button("Prev",0,function()c:SetValue(math.max(1,c.Value-1));render();if callback then callback(c.Value)end end);button("Next",1, function()c:SetValue(math.min(pages or 1,c.Value+1));render();if callback then callback(c.Value)end end);render();return c end
